begin;
select no_plan();
create function pg_temp.p_id(text)returns uuid language sql immutable as $$select md5('privacy-fixture:'||$1)::uuid$$;
insert into auth.users(id,email,email_confirmed_at,created_at,raw_user_meta_data)values
  (pg_temp.p_id('manager'),'privacy-manager@example.test',now(),now(),jsonb_build_object('varsity_role','none','varsity_programs','[]'::jsonb,'display_name','Privacy manager','beta_age_eligible',true,'beta_eligibility_year',extract(year from timezone('America/Toronto',now()))::integer,'beta_eligibility_policy_version','brock-beta-eligibility-2026-10-06.1')),
  (pg_temp.p_id('unverified'),'unused@example.test',null,now()-interval '31 days',jsonb_build_object('display_name','Unused account','varsity_role','none','varsity_programs','[]'::jsonb,'beta_age_eligible',true,'beta_eligibility_year',extract(year from timezone('America/Toronto',now()))::integer,'beta_eligibility_policy_version','brock-beta-eligibility-2026-10-06.1'));
insert into auth.sessions(id,user_id,aal)values(pg_temp.p_id('manager'),pg_temp.p_id('manager'),'aal1');
select set_config('request.jwt.claim.sub',pg_temp.p_id('manager')::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.p_id('manager'),'role','authenticated','aal','aal1','session_id',pg_temp.p_id('manager'))::text,true);
set local role authenticated;
select throws_ok($$select public.claim_service_email_jobs()$$,'42501',null,'members cannot claim operator email jobs');
select throws_ok($$select public.export_erasure_ledger()$$,'42501',null,'members cannot export erased account identifiers');
select throws_ok($$select public.erase_account(pg_temp.p_id('manager'))$$,'42501',null,'account erasure requires the verified server boundary');
select throws_ok($$select beta_private.process_retention()$$,'42501',null,'members cannot execute retention');
select throws_ok($$select * from beta_private.retention_cases$$,'42501',null,'case records are private');
select is((public.get_service_email_preferences()->>'draft_updates')::boolean,true,'draft notices have an explicit configurable default');
select lives_ok($$select public.set_service_email_preferences(false)$$,'member can stop optional draft email without signing out');
reset role;
update beta_private.release_controls set fresh_command_keys_required=true;
set local role authenticated;
select throws_ok($$select beta_private.begin_command('test','old-client-key')$$,'PT409','Reload the application before submitting this action','internal guards remain effective when called through authenticated commands');
reset role;
select throws_ok($$select beta_private.begin_command('test','old-client-key')$$,'PT409','Reload the application before submitting this action','legacy new executions require reload after activation');
select throws_ok($$select beta_private.begin_command('test','bf2:1000000000000:11111111-1111-4111-8111-111111111111')$$,'PT409','This action expired; review the current state before trying again','expired missing receipts cannot replay commands');
select is(beta_private.begin_command('test','bf2:'||floor(extract(epoch from clock_timestamp())*1000)::text||':'||gen_random_uuid()),null::jsonb,'fresh timestamped command may execute');
insert into public.idempotency_keys(user_id,command,idempotency_key,response,created_at)values(pg_temp.p_id('manager'),'test','old-client-key','{"preserved":true}',now()-interval '91 days');
select is(beta_private.begin_command('test','old-client-key'),' {"preserved":true}'::jsonb,'existing uncertain outcomes retain their original receipt');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(beta_private.process_retention()->>'enabled','false','installing the migration never enables destructive cleanup');
select is(beta_private.dispatch_service_email_tick(),false,'installing the migration never dispatches mail');
select throws_ok($$select public.queue_contact_message(pg_temp.p_id('contact'),'{"kind":"contact","replyEmail":"reply@example.test","message":"A genuine support request"}')$$,'55000','Contact delivery is awaiting release checks','unconfigured contact delivery fails honestly');
update beta_private.release_controls set service_email_enabled=true;
select lives_ok($$select public.queue_contact_message(pg_temp.p_id('contact'),'{"kind":"contact","replyEmail":"reply@example.test","message":"A genuine support request"}')$$,'contact enqueues once');
select lives_ok($$select public.queue_contact_message(pg_temp.p_id('contact'),'{"kind":"contact","replyEmail":"reply@example.test","message":"A genuine support request"}')$$,'uncertain contact retries reuse the job');
select is((select count(*)from beta_private.service_email_jobs where kind='contact'),1::bigint,'retry never duplicates mail');
select throws_ok($$select public.queue_contact_message(pg_temp.p_id('contact'),'{"kind":"contact","replyEmail":"reply@example.test","message":"Changed request"}')$$,'PT409','Request changed; use a new request ID','a reused key cannot silently change the request');
select throws_ok($$select public.queue_contact_message(pg_temp.p_id('bad'),'{"kind":"contact","replyEmail":"reply@example.test","message":"Request","bcc":"leak@example.test"}')$$,'22023','Enter a valid message and reply address','untrusted fields cannot add recipients');
create temp table email_batch as select public.claim_service_email_jobs()batch;
select is(jsonb_array_length((select batch from email_batch)),1,'worker claims one queued message');
select is(jsonb_array_length(public.claim_service_email_jobs()),0,'concurrent claims never duplicate an active lease');
select is(public.finish_service_email_job(((select batch from email_batch)->0->>'id')::uuid,gen_random_uuid(),'accepted','invalid-lease'),false,'stale worker cannot acknowledge another lease');
select is(public.finish_service_email_job(((select batch from email_batch)->0->>'id')::uuid,((select batch from email_batch)->0->>'leaseToken')::uuid,'accepted','test-provider'),true,'provider acceptance is distinct from delivery');
select is(public.contact_message_status(pg_temp.p_id('contact'))->>'status','accepted','queued contact reports actual provider acceptance');
select is(public.record_service_email_event('test-provider','delivered'),true,'verified delivery event advances the state');
select is(public.contact_message_status(pg_temp.p_id('contact'))->>'status','delivered','contact delivery is confirmed only by provider event');
select is(public.contact_message_status(pg_temp.p_id('unknown'))->>'status','unknown','unknown references reveal no message data');
insert into public.notifications(id,user_id,kind,title,body)values(pg_temp.p_id('account-mail'),pg_temp.p_id('manager'),'account_inactivity','Account review','Sign in to retain this account');
create temp table race_batch as select public.claim_service_email_jobs()batch;
select is(jsonb_array_length((select batch from race_batch)),1,'essential account notice is separate from opted-out draft email');
select is(public.record_service_email_event('race-provider','bounced'),true,'early provider events are durably recorded before acceptance');
select public.finish_service_email_job(((select batch from race_batch)->0->>'id')::uuid,((select batch from race_batch)->0->>'leaseToken')::uuid,'accepted','race-provider');
select is((select status from beta_private.service_email_jobs where provider_id='race-provider'),'bounced','acceptance reconciliation preserves a racing bounce');
select ok((select suppressed from beta_private.service_email_preferences where user_id=pg_temp.p_id('manager')),'a definitive bounce suppresses further mail to that account');
insert into public.notifications(id,user_id,kind,title,body,created_at)values
  (pg_temp.p_id('expired'),pg_temp.p_id('manager'),'test','Expired','Expired',now()-interval '91 days'),
  (pg_temp.p_id('held'),pg_temp.p_id('manager'),'test','Held','Held',now()-interval '91 days'),
  (pg_temp.p_id('current'),pg_temp.p_id('manager'),'test','Current','Current',now());
insert into beta_private.retention_holds(category,record_key,reason,expires_at)values('public.notifications',pg_temp.p_id('held')::text,'Open documented dispute review',now()+interval '30 days');
update beta_private.release_controls set retention_enabled=true;
select lives_ok($$select beta_private.process_retention(100)$$,'bounded retention worker completes');
select is((select count(*)from public.notifications where id=pg_temp.p_id('expired')),0::bigint,'old notifications expire');
select is((select count(*)from public.notifications where id=pg_temp.p_id('current')),1::bigint,'current notifications remain');
select is((select count(*)from public.notifications where id=pg_temp.p_id('held')),1::bigint,'a documented hold preserves the selected record');
select is((select count(*)from auth.users where id=pg_temp.p_id('unverified')),0::bigint,'unverified accounts expire after 30 days');
select ok(exists(select 1 from beta_private.erasure_ledger where entity_id=pg_temp.p_id('unverified')and entity_kind='account'),'deleted identities enter the backup replay ledger');
select ok(exists(select 1 from jsonb_array_elements(public.export_erasure_ledger()->'entries')e where e->>'id'=pg_temp.p_id('unverified')::text),'fresh deletion exports include removals after older backups');
select is((select count(*)from public.idempotency_keys where idempotency_key='old-client-key'),0::bigint,'expired receipts are pruned only with replay prevention enabled');
update beta_private.retention_holds set expires_at=now()-interval '1 second';
select beta_private.process_retention(100);
select is((select count(*)from public.notifications where id=pg_temp.p_id('held')),0::bigint,'released holds allow the next bounded run to dispose records');
insert into beta_private.retention_cases(id,kind,closed_at,verification_evidence,verified_at)values(pg_temp.p_id('case'),'privacy',now()-interval '1 month','{"document":"sensitive"}',now()-interval '31 days');
insert into beta_private.retention_cases(id,kind,determined_at,closed_at)values(pg_temp.p_id('breach'),'breach',now()-interval '23 months',now()-interval '1 month');
select beta_private.process_retention(100);
select is((select verification_evidence from beta_private.retention_cases where id=pg_temp.p_id('case')),null::jsonb,'verification evidence expires after 30 days');
select ok(exists(select 1 from beta_private.retention_cases where id=pg_temp.p_id('breach')),'breach record is retained at least 24 months from determination');
create table public.retention_test_parent(id uuid primary key);
create table public.retention_test_child(id uuid primary key,parent_id uuid references public.retention_test_parent(id));
insert into public.retention_test_parent values(pg_temp.p_id('parent'));
insert into public.retention_test_child select pg_temp.p_id(n::text),pg_temp.p_id('parent')from generate_series(1,5)n;
select is(beta_private.expire_tree('public.retention_test_parent','true',2,clock_timestamp()),2,'foreign-key cleanup respects its total row budget');
select is((select count(*)from public.retention_test_child),3::bigint,'large child sets make bounded resumable progress');
select is((select count(*)from public.retention_test_parent),1::bigint,'parent remains until every dependant is removed');
select is(beta_private.expire_tree('public.retention_test_parent','true',5,clock_timestamp()),4,'a later run completes children and parent');
select is((select count(*)from public.retention_test_parent),0::bigint,'repeatable expiry completes without a cascade spike');
select is(beta_private.expire_tree('public.retention_test_parent','true',5,clock_timestamp()),0,'cleanup rerun is idempotent');
insert into public.source_imports(id,source,source_hash,kind,payload,status,imported_by)values(pg_temp.p_id('retained-source'),'Approved fixture','privacy-fixture','roster','{}','published',pg_temp.p_id('manager'));
update public.player_pools set rankings_approved_by=pg_temp.p_id('manager')where id='b0000000-0000-4000-8000-000000000003';
insert into beta_private.retention_holds(category,record_key,reason,expires_at)values('account',pg_temp.p_id('manager')::text,'Verified open privacy request hold',now()+interval '30 days');
select throws_ok($$select public.erase_account(pg_temp.p_id('manager'))$$,'PT409','Contact Ty to review the active privacy or dispute hold before deleting this account','account deletion respects a scoped hold');
delete from beta_private.retention_holds where category='account';
select is(public.erase_account(pg_temp.p_id('manager')),true,'account erasure succeeds atomically despite restrictive source references');
select ok(not exists(select 1 from auth.users where id=pg_temp.p_id('manager')),'erasure revokes the identity and its sessions');
select ok(exists(select 1 from public.source_imports where id=pg_temp.p_id('retained-source')and imported_by is null),'approved source records survive account deletion without their submitter reference');
select * from finish();
rollback;
